            elif color == 2:
                cells = [(r, c - k) for k in range(1, 5)]
            elif color == 3:
                cells = [(r + k, c) for k in range(1, 4)]
            elif color == 6:
                cells = [(r - k, c) for k in range(1, 7)]
            else:
                continue

            cells = [(rr, cc) for rr, cc in cells
                     if 0 <= rr < h and 0 <= cc < w]
            if cells:
                rays.append((color, cells))

    counts = {}
    for color, cells in rays:
        for cell in cells:
            counts[cell] = counts.get(cell, 0) + 1

    crossings = {cell for cell, n in counts.items() if n > 1}

    for color, cells in rays:
        for i, (r, c) in enumerate(cells):
            if (r, c) in crossings:
                continue
            if i == len(cells) - 1:
                out[r][c] = color
            elif out[r][c] == 0:
                out[r][c] = 5

    for r, c in crossings:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1

    return out
